///$tab Main
SET ThousandSep=',';
SET DecimalSep='.';
SET MoneyThousandSep=',';
SET MoneyDecimalSep='.';
SET MoneyFormat='$ ###0.00;-$ ###0.00';
SET TimeFormat='h:mm:ss TT';
SET DateFormat='M/D/YYYY';
SET TimestampFormat='M/D/YYYY h:mm:ss[.fff] TT';
SET FirstWeekDay=6;
SET BrokenWeeks=1;
SET ReferenceDay=0;
SET FirstMonthOfYear=1;
SET CollationLocale='en-US';
SET CreateSearchIndexOnReload=1;
SET MonthNames='Jan;Feb;Mar;Apr;May;Jun;Jul;Aug;Sep;Oct;Nov;Dec';
SET LongMonthNames='January;February;March;April;May;June;July;August;September;October;November;December';
SET DayNames='Mon;Tue;Wed;Thu;Fri;Sat;Sun';
SET LongDayNames='Monday;Tuesday;Wednesday;Thursday;Friday;Saturday;Sunday';
SET NumericalAbbreviation='3:k;6:M;9:G;12:T;15:P;18:E;21:Z;24:Y;-3:m;-6:μ;-9:n;-12:p;-15:f;-18:a;-21:z;-24:y';

///$tab Data_Load
LIB CONNECT TO 'Trial:snowflake_connection';


//======================================================
// CUSTOMERS
//======================================================

Customers:
SQL SELECT
    CUSTOMERID,
    ACCOUNTNAME,
    CUSTOMERTYPE,
    REGION AS CUSTOMER_REGION,
    COUNTRY,
    SALESREP
FROM QLIK_DEMO_DB.RETAIL.CUSTOMERS;


//======================================================
// PRODUCTS
//======================================================

Products:
SQL SELECT
    PRODUCTID,
    ITEMDESC,
    BRAND,
    STYLE,
    PRODUCTCATEGORY,
    INVENTORYCLASS,
    UOM,
    STANDARDCOST,
    LISTPRICE
FROM QLIK_DEMO_DB.RETAIL.PRODUCTS;


//======================================================
// SALES FACT
//======================================================

Sales:
LOAD
    *,
    Date(Date#(SALESDATEKEY, 'YYYYMMDD')) AS SalesDate,
    Year(Date#(SALESDATEKEY, 'YYYYMMDD')) AS SalesYear,
    Month(Date#(SALESDATEKEY, 'YYYYMMDD')) AS SalesMonth,
    Year(Date#(SALESDATEKEY, 'YYYYMMDD')) & '-' &
        Num(Month(Date#(SALESDATEKEY, 'YYYYMMDD')), '00') AS SalesYearMonth;

SQL SELECT
    SALESID,
    DATEKEY AS SALESDATEKEY,
    CUSTOMERID,
    PRODUCTID,
    LOCATIONID AS SALESLOCATIONID,
    ORDERID,
    DATETYPE,
    SALESCHANNEL,
    SHIPQTY,
    GROSSSALES,
    DISCOUNTPCT,
    DISCOUNTAMOUNT,
    SALESAMOUNT,
    COSTAMOUNT,
    GROSSPROFIT,
    BOOKINGAMOUNT,
    INVOICEAMOUNT
FROM QLIK_DEMO_DB.RETAIL.SALES;


//======================================================
// INVENTORY FACT
//======================================================

Inventory:
SQL SELECT
    INVENTORYID,
    DATEKEY AS INVENTORYDATEKEY,
    PRODUCTID,
    LOCATIONID AS INVENTORYLOCATIONID,
    PERIOD,
    PERIODQTY
FROM QLIK_DEMO_DB.RETAIL.INVENTORY;
